using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.SubQuorum;

internal sealed class C4RepresentativeBoundsDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Combinatorics/Graph/SubQuorum/C4RepresentativeBounds.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/Certificates/omega2026starformingfamily");
    private static DocumentBlock Node(string name, string title, string text, DescribeRole role) =>
        Describe.Lean(DescribeId.Create(name.Replace('_', '-').Replace('.', '-').ToLowerInvariant()), DeclarationHandle.Create(Prefix + name[(name.LastIndexOf('.') + 1)..]),
            H(title), StatementSource.WithoutFormula(), AssessedProvenance.FromLiterature(Source),
            Blocks(Paragraph(Text(text))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "General C4-free representative bounds", H("General C4-free representative bounds"),
        Blocks(Paragraph(Text("Actual finite representative maxima and graph-level pair ownership prove beta<=psiSq<=Omega, the equal-side regular C4-free threshold, positive-excess matching budgets and support rigidity. Projective-plane specializations keep their precise degree, cardinality and unique-pair hypotheses. These proofs concern arbitrary finite graphs; they do not assert rectangular-grid equality.")),
            Node("NoFourCycle", "NoFourCycle", "Exact declaration: def NoFourCycle {Vertex : Type} (adjacency : Vertex → Vertex → Prop) : Prop.", DescribeRole.Definition),
            Node("neighbor_pair_unique_owner", "neighbor pair unique owner", "Exact declaration: theorem neighbor_pair_unique_owner {Vertex : Type} {adjacency : Vertex → Vertex → Prop} (hfree : NoFourCycle adjacency) (first second left right : Vertex) (hpair : left ≠ right) (hfirstLeft : first ≠ left) (hfirstRight : first ≠ right) (hsecondLeft : second ≠ left) (hsecondRight : second ≠ right) (hfirstEdge : adjacency first left) (hfirstOther : adjacency first right) (hsecondEdge : adjacency second left) (hsecondOther : adjacency second right) : first = second.", DescribeRole.Theorem),
            Node("pair_packing", "pair packing", "Exact declaration: theorem pair_packing {V : Type} [DecidableEq V] (G : SimpleGraph V) [DecidableRel G.Adj] (hfree : NoFourCycle G.Adj) (U B : Finset V) (hUB : Disjoint U B) : (∑ u ∈ U, ((B.filter (G.Adj u)).card * ((B.filter (G.Adj u)).card - 1))) ≤ B.card * (B.card - 1).", DescribeRole.Theorem),
            Node("pair_packing_lower", "pair packing lower", "Exact declaration: theorem pair_packing_lower {V : Type} [DecidableEq V] (G : SimpleGraph V) [DecidableRel G.Adj] (hfree : NoFourCycle G.Adj) (U B : Finset V) (hUB : Disjoint U B) (k : ℕ) (hk : ∀ u ∈ U, k ≤ (B.filter (G.Adj u)).card) : k * (k - 1) * U.card ≤ B.card * (B.card - 1).", DescribeRole.Theorem),
            Node("endpoints", "endpoints", "Exact declaration: def endpoints (M : Finset (V × V)) : Finset V.", DescribeRole.Definition),
            Node("Feasible", "Feasible", "Exact declaration: structure Feasible (T : Finset V) (M : Finset (V × V)) : Prop.", DescribeRole.Definition),
            Node("Omega", "Omega", "Exact declaration: noncomputable def Omega : ℕ. The supremum ranges over all actual feasible singleton and matching pairs.", DescribeRole.Definition),
            Node("objective_le_omega", "objective le omega", "Exact declaration: theorem objective_le_omega (T : Finset V) (M : Finset (V × V)) (h : Feasible G T M) : T.card + M.card ≤ Omega G.", DescribeRole.Theorem),
            Node("omega_upper_of_objective_bound", "Omega upper from all feasible pairs", "Exact declaration: theorem omega_upper_of_objective_bound (n : ℕ) (h : ∀ T M, Feasible G T M → T.card + M.card ≤ n) : Omega G ≤ n. The finite Pappus maximum is its actual consumer.", DescribeRole.Theorem),
            Node("dissociation_feasible", "dissociation feasible", "Exact declaration: theorem dissociation_feasible (T : Finset V) (hT : IsKIndependent G 2 T) : Feasible G T ∅.", DescribeRole.Theorem),
            Node("positive_excess_budget", "positive excess budget", "Exact declaration: theorem positive_excess_budget (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hD : 3 ≤ D) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) (hexcess : N < T.card + M.card) : (M.card : ℤ) + ((T.card : ℤ) + M.card - N) ≤ (N : ℤ) - 2 * ((D - 1) * (D - 2) : ℕ) - 4.", DescribeRole.Theorem),
            Node("objective_threshold", "objective threshold", "Exact declaration: theorem objective_threshold (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hD : 3 ≤ D) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (hN : N ≤ 2 * (D - 1) * (D - 2) + 4) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) : T.card + M.card ≤ N.", DescribeRole.Theorem),
            Node("objective_general_bound", "objective general bound", "Exact declaration: theorem objective_general_bound (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hD : 3 ≤ D) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) : T.card + M.card ≤ max N (2*N - 2*((D-1)*(D-2)) - 4).", DescribeRole.Theorem),
            Node("first_excess_matching_empty", "first excess matching empty", "Exact declaration: theorem first_excess_matching_empty (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hD : 3 ≤ D) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (hN : N = 2*((D-1)*(D-2))+5) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) (hc : T.card + M.card = N+1) : M = ∅.", DescribeRole.Theorem),
            Node("zero_excess_unused", "zero excess unused", "Exact declaration: theorem zero_excess_unused (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) (hc : T.card + M.card = N) (c : Bool) : (unusedSide T M color c).card = 0 ∨ (D-1)*(D-2)+1 ≤ (unusedSide T M color c).card.", DescribeRole.Theorem),
            Node("objective_one_side_support", "objective one side support", "Exact declaration: theorem objective_one_side_support (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (hN : N ≤ 2*((D-1)*(D-2))+1) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) (hc : T.card + M.card = N) : ∃ c : Bool, (∀ v ∈ T, color v = c) ∧ (∀ v, color v = c → v ∈ T ∪ endpoints M).", DescribeRole.Theorem),
            Node("coloring_representatives", "coloring representatives", "Exact declaration: theorem coloring_representatives {C : Type} [DecidableEq C] (c : V → Option C) (hc : IsSubQuorum G c) : ∃ T : Finset V, ∃ M : Finset (V × V), Feasible G T M ∧ T.card + M.card = (palette c Finset.univ).card ∧ (M = ∅ → ∀ v w, c v ≠ none → c w = c v → ¬ G.Adj v w).", DescribeRole.Theorem),
            Node("palette_le_omega", "palette le omega", "Exact declaration: theorem palette_le_omega {C : Type} [DecidableEq C] (c : V → Option C) (hc : IsSubQuorum G c) : (palette c Finset.univ).card ≤ Omega G.", DescribeRole.Theorem),
            Node("psiSq_le_omega", "psiSq le omega", "Exact declaration: theorem psiSq_le_omega : psiSq G ≤ Omega G.", DescribeRole.Theorem),
            Node("parameter_comparison", "parameter comparison", "Exact declaration: theorem parameter_comparison : beta G 2 ≤ psiSq G ∧ psiSq G ≤ Omega G.", DescribeRole.Theorem),
            Node("threshold_parameters", "threshold parameters", "Exact declaration: theorem threshold_parameters (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (D N : ℕ) (hD : 3 ≤ D) (hr : ∀ v, DegreeCapacity.degree G v = D) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = N) (hN : N ≤ 2 * (D - 1) * (D - 2) + 4) : beta G 2 = N ∧ psiSq G = N ∧ Omega G = N.", DescribeRole.Theorem),
            Node("plane_parameter_specialization", "plane parameter specialization", "Exact declaration: theorem plane_parameter_specialization (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (q : ℕ) (hq : 2 ≤ q) (hr : ∀ v, DegreeCapacity.degree G v = q + 1) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = q*q+q+1) : beta G 2 = q*q+q+1 ∧ psiSq G = q*q+q+1 ∧ Omega G = q*q+q+1.", DescribeRole.Theorem),
            Node("plane_optimal_support", "plane optimal support", "Exact declaration: theorem plane_optimal_support (color : V → Bool) (hcolor : ∀ v w, G.Adj v w → color v ≠ color w) (hfree : NoFourCycle G.Adj) (q : ℕ) (hq : 3 ≤ q) (hr : ∀ v, DegreeCapacity.degree G v = q+1) (hsides : ∀ c, (Finset.univ.filter (fun v => color v = c)).card = q*q+q+1) (T : Finset V) (M : Finset (V × V)) (hf : Feasible G T M) (hc : T.card+M.card = q*q+q+1) : ∃ c : Bool, (∀ v ∈ T, color v = c) ∧ (∀ v, color v = c → v ∈ T ∪ endpoints M).", DescribeRole.Theorem)), []));
}
